function updateHUD(){
    if(!currentRoomData)return;let myTotalHp=1.0;if(myEquipped.hull&&MODULES[myEquipped.hull])myTotalHp*=MODULES[myEquipped.hull].stats.hp||1;if(myEquipped.turret&&MODULES[myEquipped.turret])myTotalHp*=MODULES[myEquipped.turret].stats.hp||1;if(myEquipped.tracks&&MODULES[myEquipped.tracks])myTotalHp*=MODULES[myEquipped.tracks].stats.hp||1;let myMaxHp=Math.round(MAX_HP*myTotalHp);let hpPct=Math.max(0,(myLocalTank.hp/myMaxHp)*100)+'%';document.getElementById('hp-bar').style.width=hpPct;document.getElementById('hp-text').innerText=`${Math.ceil(myLocalTank.hp)}/${myMaxHp}`;if(document.getElementById('hp-bar-mob')){document.getElementById('hp-bar-mob').style.width=hpPct;document.getElementById('hp-text-mob').innerText=`${Math.ceil(myLocalTank.hp)}/${myMaxHp}`;}
    let vignetteOpacity=0;if(myLocalTank.hp<myMaxHp)vignetteOpacity=(1-(myLocalTank.hp/myMaxHp))*0.85;document.getElementById('damage-vignette').style.opacity=vignetteOpacity;let barClass=myLocalTank.hp<myMaxHp*0.3?'h-full bg-gradient-to-r from-red-600 to-red-400 w-full transition-all duration-300 shadow-[0_0_15px_rgba(239,68,68,0.8)]':'h-full bg-gradient-to-r from-green-500 to-emerald-400 w-full transition-all duration-300 shadow-[0_0_10px_rgba(34,197,94,0.5)]';document.getElementById('hp-bar').className=barClass;if(document.getElementById('hp-bar-mob'))document.getElementById('hp-bar-mob').className=barClass;const targetUI=document.getElementById('homing-target-ui');if(myLocalTank.buff==='homing')targetUI.classList.remove('hidden');else targetUI.classList.add('hidden');
    const dmHud=document.getElementById('deathmatch-score-hud'),survHud=document.getElementById('survival-hud'),pcCd=document.getElementById('pc-cd-container'),mobCd=document.getElementById('mob-cd-container'),slist=document.getElementById('score-list');
    if(currentRoomData.mode==='prophunt'){dmHud.classList.add('hidden');survHud.classList.add('hidden');if(myLocalTank.team==='hider'){if(pcCd)pcCd.classList.add('hidden');if(mobCd)mobCd.classList.add('hidden');}else{if(pcCd)pcCd.classList.remove('hidden');if(mobCd)mobCd.classList.remove('hidden');}}else if(currentRoomData.mode==='survival'){dmHud.classList.add('hidden');survHud.classList.remove('hidden');if(pcCd)pcCd.classList.remove('hidden');if(mobCd)mobCd.classList.remove('hidden');const wvNum=document.getElementById('survival-wave-number'),wvBox=document.getElementById('survival-wave-box');wvNum.innerText=currentRoomData.wave;if(isBossIncoming){wvBox.className="glass-panel px-4 lg:px-10 py-1 lg:py-2 rounded-xl lg:rounded-2xl border flex flex-col items-center transition-colors duration-300 border-red-500 bg-red-900/40 shadow-[0_0_20px_rgba(239,68,68,0.5)]";wvNum.className="text-xl lg:text-4xl font-russo drop-shadow-md text-red-500 leading-none";}else{wvBox.className="glass-panel px-4 lg:px-10 py-1 lg:py-2 rounded-xl lg:rounded-2xl border border-slate-600 flex flex-col items-center transition-colors duration-500 shadow-[0_0_15px_rgba(0,0,0,0.5)] bg-slate-900/80";wvNum.className="text-xl lg:text-4xl font-russo text-white drop-shadow-md leading-none";}}else{dmHud.classList.remove('hidden');survHud.classList.add('hidden');if(pcCd)pcCd.classList.remove('hidden');if(mobCd)mobCd.classList.remove('hidden');slist.innerHTML='';Object.values(currentRoomData.players).sort((a,b)=>b.score-a.score).forEach(p=>{slist.innerHTML+=`<div class="flex justify-between w-full ${p.id===myId?'text-blue-400':'text-slate-300'} border-b border-slate-700/50 pb-1 ${p.hp<=0?'opacity-30 line-through':''}"><span>${p.name}</span><span class="font-bold">${p.score}</span></div>`;});}
    if(isMobile){if(myLocalTank.buff==='homing'&&myLocalTank.hp>0)document.getElementById('mobile-target-btn').classList.remove('hidden');else document.getElementById('mobile-target-btn').classList.add('hidden');if(myLocalTank.hp<=0&&(currentRoomData.mode==='survival'||currentRoomData.mode==='prophunt')){document.getElementById('mobile-spec-prev').classList.remove('hidden');document.getElementById('mobile-spec-next').classList.remove('hidden');}else{document.getElementById('mobile-spec-prev').classList.add('hidden');document.getElementById('mobile-spec-next').classList.add('hidden');}}
}

function startGameLoop(){if(gameLoopId)cancelAnimationFrame(gameLoopId);lastTime=performance.now();requestAnimationFrame(gameLoop);}
function gameLoop(now){const dt=Math.min((now-lastTime)/1000,0.1);lastTime=now;if(currentRoomData&&currentRoomData.status==='playing'){updatePhysics(now,dt);draw(now);}gameLoopId=requestAnimationFrame(gameLoop);}

window.addEventListener('keydown',e=>{if(!e||!e.key)return;const k=e.key.toLowerCase();if(keys.hasOwnProperty(k)||k===' '){if(k===' ')keys.space=true;else keys[k]=true;}if(myLocalTank.hp<=0&&currentRoomData&&(currentRoomData.mode==='survival'||currentRoomData.mode==='prophunt')){if(k==='a')findNextSpectateTarget(-1);if(k==='d')findNextSpectateTarget(1);}if(e.key==='Tab'){e.preventDefault();if(myLocalTank.buff==='homing'){let visibleOps=Object.keys(opponents).filter(id=>opponents[id].hp>0&&Math.hypot(opponents[id].x-myLocalTank.x,opponents[id].y-myLocalTank.y)<1500);if(visibleOps.length>0){playSound('hitmarker');if(!homingTargetId||!visibleOps.includes(homingTargetId))homingTargetId=visibleOps[0];else{let idx=visibleOps.indexOf(homingTargetId);homingTargetId=visibleOps[(idx+1)%visibleOps.length];}}else homingTargetId=null;}}});
window.addEventListener('keyup',e=>{if(!e||!e.key)return;const k=e.key.toLowerCase();if(keys.hasOwnProperty(k)||k===' '){if(k===' ')keys.space=false;else keys[k]=false;}});
window.addEventListener('mousemove',e=>{if(!isMobile){mouseX=e.clientX;mouseY=e.clientY;}});
window.addEventListener('mousedown',e=>{if(!isMobile&&e.button===0&&e.target.id==='game-canvas')keys.lmb=true;});
window.addEventListener('mouseup',e=>{if(!isMobile&&e.button===0)keys.lmb=false;});

function handleTouchStart(e){if(!isMobile||myLocalTank.hp<=0)return;for(let i=0;i<e.changedTouches.length;i++){let t=e.changedTouches[i];if(t.clientX<canvas.width/2&&!joysticks.left.active){joysticks.left.active=true;joysticks.left.id=t.identifier;joysticks.left.startX=t.clientX;joysticks.left.startY=t.clientY;joysticks.left.currentX=t.clientX;joysticks.left.currentY=t.clientY;}else if(t.clientX>=canvas.width/2&&!joysticks.right.active){joysticks.right.active=true;joysticks.right.id=t.identifier;joysticks.right.startX=t.clientX;joysticks.right.startY=t.clientY;joysticks.right.currentX=t.clientX;joysticks.right.currentY=t.clientY;joysticks.right.hasAimed=false;joysticks.right.released=false;}}}
function handleTouchMove(e){if(!isMobile||myLocalTank.hp<=0)return;for(let i=0;i<e.changedTouches.length;i++){let t=e.changedTouches[i];if(joysticks.left.active&&t.identifier===joysticks.left.id){let dx=t.clientX-joysticks.left.startX,dy=t.clientY-joysticks.left.startY,dist=Math.hypot(dx,dy),maxDist=60;if(dist>maxDist){dx=(dx/dist)*maxDist;dy=(dy/dist)*maxDist;}joysticks.left.currentX=joysticks.left.startX+dx;joysticks.left.currentY=joysticks.left.startY+dy;joysticks.left.angle=Math.atan2(dy,dx);joysticks.left.force=Math.min(1,dist/maxDist);}else if(joysticks.right.active&&t.identifier===joysticks.right.id){let dx=t.clientX-joysticks.right.startX,dy=t.clientY-joysticks.right.startY,dist=Math.hypot(dx,dy),maxDist=60;if(dist>10)joysticks.right.hasAimed=true;if(dist>maxDist){dx=(dx/dist)*maxDist;dy=(dy/dist)*maxDist;}joysticks.right.currentX=joysticks.right.startX+dx;joysticks.right.currentY=joysticks.right.startY+dy;joysticks.right.angle=Math.atan2(dy,dx);}}}
function handleTouchEnd(e){if(!isMobile||myLocalTank.hp<=0)return;for(let i=0;i<e.changedTouches.length;i++){let t=e.changedTouches[i];if(joysticks.left.active&&t.identifier===joysticks.left.id){joysticks.left.active=false;joysticks.left.id=null;joysticks.left.force=0;}else if(joysticks.right.active&&t.identifier===joysticks.right.id){if(joysticks.right.hasAimed)joysticks.right.released=true;joysticks.right.active=false;joysticks.right.id=null;joysticks.right.hasAimed=false;}}}

canvas.addEventListener('touchstart',handleTouchStart,{passive:false});canvas.addEventListener('touchmove',handleTouchMove,{passive:false});canvas.addEventListener('touchend',handleTouchEnd,{passive:false});canvas.addEventListener('touchcancel',handleTouchEnd,{passive:false});

const targetBtn=document.getElementById('mobile-target-btn');if(targetBtn)targetBtn.addEventListener('touchstart',(e)=>{e.preventDefault();e.stopPropagation();if(myLocalTank.buff==='homing'){let visibleOps=Object.keys(opponents).filter(id=>opponents[id].hp>0&&Math.hypot(opponents[id].x-myLocalTank.x,opponents[id].y-myLocalTank.y)<1500);if(visibleOps.length>0){playSound('hitmarker');if(!homingTargetId||!visibleOps.includes(homingTargetId))homingTargetId=visibleOps[0];else{let idx=visibleOps.indexOf(homingTargetId);homingTargetId=visibleOps[(idx+1)%visibleOps.length];}}else homingTargetId=null;}},{passive:false});
const specPrev=document.getElementById('mobile-spec-prev');if(specPrev)specPrev.addEventListener('touchstart',(e)=>{e.preventDefault();e.stopPropagation();findNextSpectateTarget(-1);},{passive:false});
const specNext=document.getElementById('mobile-spec-next');if(specNext)specNext.addEventListener('touchstart',(e)=>{e.preventDefault();e.stopPropagation();findNextSpectateTarget(1);},{passive:false});